breach.segment:
// Breach: at least 20% of the zone's VMs AND at least 2 VMs are saturated.
// Lower saturated_instances to 1 for small fleets where every VM matters.
WHERE saturated_pct >= 20 AND saturated_instances >= 2
| KEEP resource.attributes.project_id, resource.attributes.zone, saturated_pct, saturated_instances, instances, zone_avg_cpu_util, max_cpu_util, saturated_instance_names
| SORT saturated_pct DESC
| LIMIT 50
